partitions = {
    "2026-Q1": [{"id": "d1", "date": "2026-02-10"}, {"id": "d2", "date": "2026-03-15"}],
    "2026-Q2": [{"id": "d3", "date": "2026-05-01"}],
    "2025-Q4": [{"id": "d4", "date": "2025-11-20"}],
}

def prune_partitions(partitions, start_quarter):
    return {key: docs for key, docs in partitions.items() if key >= start_quarter}

def search_relevant_partitions(partitions, start_quarter):
    relevant = prune_partitions(partitions, start_quarter)
    results = []
    for docs in relevant.values():
        results.extend(docs)
    return results

print(f"Total partitions in collection: {len(partitions)}")

pruned = prune_partitions(partitions, "2026-Q1")
print(f"Partitions remaining after pruning to 2026-Q1 onward: {list(pruned.keys())}")

results = search_relevant_partitions(partitions, "2026-Q1")
print(f"\nDocuments found in relevant partitions only:")
for r in results:
    print(f"  {r}")
